import {assert,date,point,available,coordinates,orderedRoute,businessToday} from "./planificacion-domain.mjs";
export function weekWindow(reference=businessToday(),weeksAhead=0){date(reference);assert(Number.isInteger(weeksAhead)&&weeksAhead>=0&&weeksAhead<=52,"Antelación de 0 a 52 semanas.");const d=new Date(`${reference}T12:00:00Z`);d.setUTCDate(d.getUTCDate()-((d.getUTCDay()+6)%7)+weeksAhead*7);const start=d.toISOString().slice(0,10);d.setUTCDate(d.getUTCDate()+6);return{start,end:d.toISOString().slice(0,10)};}

export function defaultWeeklySettings(technicianId){return{enabled:false,weeksAhead:3,capacity:6,minutes:480,weekdays:[1,2,3,4,5],technicianIds:technicianId?[technicianId]:[],origin:null,destination:null,originLabel:"Avenida de Cuba 34, Benalmádena, 29631 Málaga",destinationLabel:""};}

export function validateWeeklySettings(input,memberIds){assert(input&&typeof input==="object","Configuración semanal inválida.");weekWindow("2030-01-07",input.weeksAhead);assert(typeof input.enabled==="boolean","Indica si quieres generación automática.");assert(Number.isInteger(input.capacity)&&input.capacity>=1&&input.capacity<=14,"Capacidad de 1 a 14 visitas.");assert(Number.isInteger(input.minutes)&&input.minutes>=30&&input.minutes<=1440,"Minutos de intervención inválidos.");assert(Array.isArray(input.weekdays)&&input.weekdays.length&&input.weekdays.every(x=>Number.isInteger(x)&&x>=0&&x<=6),"Selecciona días laborables.");assert(Array.isArray(input.technicianIds)&&input.technicianIds.length&&input.technicianIds.length<=100&&input.technicianIds.every(x=>memberIds.includes(x)),"Selecciona técnicos de esta empresa.");point(input.origin);point(input.destination);for(const k of ["originLabel","destinationLabel"])assert(input[k]===undefined||(typeof input[k]==="string"&&input[k].length<=300),"Dirección inválida.");return{enabled:input.enabled,weeksAhead:input.weeksAhead,capacity:input.capacity,minutes:input.minutes,weekdays:[...new Set(input.weekdays)].sort(),technicianIds:[...new Set(input.technicianIds)].sort(),origin:[...input.origin],destination:[...input.destination],originLabel:input.originLabel??"",destinationLabel:input.destinationLabel??""};}

export function buildWeeklyDraft({settings,clients,visits,plans,today=businessToday()}){const window=weekWindow(today,settings.weeksAhead),slots=[],groups=[],unassigned=[];const clientMap=new Map(clients.filter(c=>!c.archived).map(c=>[c.id,c]));const busy=new Set(visits.filter(v=>["planned","proposed","confirmed"].includes(v.status)).map(v=>v.client_id));const d=new Date(`${window.start}T12:00:00Z`);for(let i=0;i<7;i++,d.setUTCDate(d.getUTCDate()+1)){const day=d.toISOString().slice(0,10);if(day<today||!settings.weekdays.includes(d.getUTCDay()))continue;for(const technicianId of settings.technicianIds){const existing=plans.find(p=>p.day===day&&p.technician_id===technicianId),assigned=existing?visits.filter(v=>v.plan_id===existing.id):[];slots.push({existingPlanId:existing?.id??null,day,technicianId,name:existing?.name??`Semana ${window.start}`,capacity:Math.min(settings.capacity,existing?.capacity??settings.capacity),minutes:Math.min(settings.minutes,existing?.minutes??settings.minutes),origin:existing?.origin??settings.origin,destination:existing?.destination??settings.destination,existingCount:assigned.length,existingMinutes:assigned.reduce((n,v)=>n+v.duration,0),assigned,visits:[]});}}
const candidates=visits.filter(v=>v.status==="pool"&&v.due_date<=window.end&&clientMap.has(v.client_id)).sort((a,b)=>a.due_date.localeCompare(b.due_date)||a.id.localeCompare(b.id));for(const v of candidates){const fail=reason=>unassigned.push({visitId:v.id,clientId:v.client_id,dueDate:v.due_date,reason});if(busy.has(v.client_id)){fail("El cliente ya tiene otra visita asignada.");continue;}const coord=coordinates(clientMap.get(v.client_id));if(!coord||coord.length!==2||!coord.every(Number.isFinite)){fail("Faltan coordenadas para agrupar.");continue;}const compatible=slots.filter(s=>available(v,s.day));if(!compatible.length){fail("Sin disponibilidad compatible en esta semana.");continue;}const onTime=compatible.filter(s=>v.due_date<(today>window.start?today:window.start)||s.day<=v.due_date);if(!onTime.length){fail("No hay un día compatible antes del vencimiento.");continue;}const fitting=onTime.filter(s=>s.existingCount+s.visits.length<s.capacity&&s.existingMinutes+s.visits.reduce((n,x)=>n+x.duration,0)+v.duration<=s.minutes);if(!fitting.length){fail("Sin capacidad o tiempo de intervención en los días compatibles.");continue;}let best;for(const s of fitting){const assigned=[...s.assigned,...s.visits.map(x=>visits.find(v=>v.id===x.visitId))],before=orderedRoute(s,assigned,clients)?.km,after=orderedRoute(s,[...assigned,v],clients)?.km;const extra=before===undefined||after===undefined?Number.MAX_SAFE_INTEGER:Math.max(0,after-before);if(!best||extra<best.extra||(extra===best.extra&&s.day<best.slot.day))best={slot:s,extra};}best.slot.visits.push({visitId:v.id,clientId:v.client_id,version:v.version,dueDate:v.due_date,duration:v.duration,late:best.slot.day>v.due_date});busy.add(v.client_id);}for(const slot of slots)if(slot.visits.length){const{assigned,...g}=slot;groups.push(g);}return{weekStart:window.start,weekEnd:window.end,groups,unassigned,candidateCount:candidates.length,assignedCount:groups.reduce((n,g)=>n+g.visits.length,0),preservedCount:visits.filter(v=>v.plan_id&&plans.some(p=>p.id===v.plan_id&&p.day>=window.start&&p.day<=window.end)).length,method:"Proximidad geográfica estimada. Minutos de intervención, sin desplazamientos."};}

export function validateWeeklyApproval({payload,clients,visits,plans,memberIds,today=businessToday()}){const seen=new Set();for(const g of payload.groups){assert(g.day>=payload.weekStart&&g.day<=payload.weekEnd&&g.day>=today,"El borrador contiene días pasados. Regénéralo.",409);assert(memberIds.includes(g.technicianId),"Un técnico ha cambiado. Regenera el borrador.",409);const plan=plans.find(p=>p.day===g.day&&p.technician_id===g.technicianId);assert((g.existingPlanId??null)===(plan?.id??null),"La agenda ha cambiado. Regenera el borrador.",409);if(plan)assert(JSON.stringify(plan.origin)===JSON.stringify(g.origin)&&JSON.stringify(plan.destination)===JSON.stringify(g.destination),"La ruta ha cambiado. Regenera el borrador.",409);const occupied=plan?visits.filter(v=>v.plan_id===plan.id):[];assert(occupied.length+g.visits.length<=Math.min(g.capacity,plan?.capacity??g.capacity)&&occupied.reduce((n,v)=>n+v.duration,0)+g.visits.reduce((n,v)=>n+v.duration,0)<=Math.min(g.minutes,plan?.minutes??g.minutes),"La capacidad ha cambiado. Regenera el borrador.",409);for(const item of g.visits){const v=visits.find(v=>v.id===item.visitId),c=clients.find(c=>c.id===item.clientId);assert(!seen.has(item.visitId)&&v&&c&&!c.archived&&v.client_id===item.clientId&&v.status==="pool"&&v.version===item.version&&v.duration===item.duration&&available(v,g.day),"Una visita ha cambiado. Regenera el borrador.",409);assert(!visits.some(other=>other.client_id===v.client_id&&["planned","proposed","confirmed"].includes(other.status)),"El cliente ya tiene otra visita asignada.",409);seen.add(item.visitId);}}return true;}
